// The current status of the issue.
type IssuesStatus string

const (
	IssuesStatusReported             IssuesStatus = "REPORTED"
	IssuesStatusAwaitingResolution   IssuesStatus = "AWAITING_RESOLUTION"
	IssuesStatusFixInProgress        IssuesStatus = "FIX_IN_PROGRESS"
	IssuesStatusFixPendingValidation IssuesStatus = "FIX_PENDING_VALIDATION"
	IssuesStatusCannotFix            IssuesStatus = "CANNOT_FIX"
	IssuesStatusResolved             IssuesStatus = "RESOLVED"
)

func NewIssuesStatusFromString(s string) (IssuesStatus, error) {
	switch s {
	case "REPORTED":
		return IssuesStatusReported, nil
	case "AWAITING_RESOLUTION":
		return IssuesStatusAwaitingResolution, nil
	case "FIX_IN_PROGRESS":
		return IssuesStatusFixInProgress, nil
	case "FIX_PENDING_VALIDATION":
		return IssuesStatusFixPendingValidation, nil
	case "CANNOT_FIX":
		return IssuesStatusCannotFix, nil
	case "RESOLVED":
		return IssuesStatusResolved, nil
	}
	var t IssuesStatus
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (i IssuesStatus) Ptr() *IssuesStatus {
	return &i
}

